-- Data fix, reviewed by Menash on 22.11.2026 (list: reviews/glued-phones-2026-11-22.xlsx in the
-- project files). The pool-file loads of 17.11 stored 199 phone rows as two or three numbers in
-- one value (for example "052-6273939 , 02-6525442"), so the number cannot be dialled.
-- Each number is added as its own phone and the combined row is marked outdated (reversible,
-- nothing is deleted). A number the supplier already has is not added again. Rows are matched by
-- id and by their current text, so the file does nothing on staging or on a row already edited.
-- Twelve rows had a typo in the source and use the fix Menash approved row by row. Two rows
-- whose correct number is unknown are left as they are.

create temporary table glued_phones (contact_id uuid primary key, old_value text, numbers text[])
  on commit drop;

