create temporary table glued_targets on commit drop as
select c.id, c.supplier_id, c.source_document_id, c.is_primary, g.numbers
from glued_phones as g
join public.supplier_contacts as c
  on c.id = g.contact_id and c.value = g.old_value and c.kind = 'phone' and c.status = 'current';

update public.supplier_contacts as c set status = 'outdated', is_primary = false
from glued_targets as t
where c.id = t.id;

insert into public.supplier_contacts (supplier_id, kind, value, source_document_id)
select distinct t.supplier_id, 'phone', n.number, t.source_document_id
from glued_targets as t
cross join lateral unnest(t.numbers) as n (number)
on conflict (supplier_id, kind, normalized_value) do nothing;

-- A supplier whose combined phone was primary gets its first number as primary instead.
update public.supplier_contacts as c set is_primary = true
from glued_targets as t
where t.is_primary
  and c.supplier_id = t.supplier_id and c.kind = 'phone' and c.status = 'current'
  and c.normalized_value = regexp_replace(t.numbers[1], '[^0-9]', '', 'g')
  and not exists (
    select 1 from public.supplier_contacts as p
    where p.supplier_id = t.supplier_id and p.kind = 'phone' and p.is_primary
  );
